#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-21

# Integration test: platform-release-watch.mjs parse + snapshot + gaps + failure paths.
# Issue: #3627 (platform release notes were structurally invisible to cc-watch).
#
# Uses PLATFORM_RELEASE_WATCH_FIXTURE to substitute the fetched markdown, so the
# test is hermetic (no network). Mirrors tests/integration/test-cc-triage.sh style.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

PASS=0
FAIL=0
log_pass() { echo -e "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
log_fail() { echo -e "  ${RED}✗${NC} $1 — $2"; FAIL=$((FAIL + 1)); }

echo "Platform Release Watch Tests (#3627)"
echo "===================================="

cd "$PROJECT_ROOT"

# Backup and restore mutated state.
GAPS_BACKUP=""
GAPS_EXISTED=0
[ -f shared/platform-adoption-gaps.json ] && { GAPS_BACKUP=$(cat shared/platform-adoption-gaps.json); GAPS_EXISTED=1; }
SUPPORT_BACKUP=""
SUPPORT_EXISTED=0
[ -f shared/platform-support.json ] && { SUPPORT_BACKUP=$(cat shared/platform-support.json); SUPPORT_EXISTED=1; }
SNAP_BACKUP_DIR=$(mktemp -d "${TMPDIR:-/tmp}/ork.XXXXXX")
[ -d shared/platform-snapshots ] && rsync -a shared/platform-snapshots/ "$SNAP_BACKUP_DIR/"
WORK_DIR=$(mktemp -d "${TMPDIR:-/tmp}/ork.XXXXXX")

restore() {
  if [ "$GAPS_EXISTED" = "1" ]; then
    echo "$GAPS_BACKUP" > shared/platform-adoption-gaps.json
  else
    rm -f shared/platform-adoption-gaps.json
  fi
  if [ "$SUPPORT_EXISTED" = "1" ]; then
    echo "$SUPPORT_BACKUP" > shared/platform-support.json
  else
    rm -f shared/platform-support.json
  fi
  rm -rf shared/platform-snapshots
  if [ -d "$SNAP_BACKUP_DIR" ] && [ -n "$(ls -A "$SNAP_BACKUP_DIR" 2>&1)" ]; then
    mkdir -p shared/platform-snapshots
    rsync -a "$SNAP_BACKUP_DIR/" shared/platform-snapshots/
  fi
  rm -rf "$SNAP_BACKUP_DIR" "$WORK_DIR"
}
trap restore EXIT

FIXTURE="$WORK_DIR/notes.md"
# pipebuf: bounded-literal
cat > "$FIXTURE" <<'EOF'
---
title: Claude Platform release notes
---

The Claude Platform release notes list changes, newest first.

<Tip>
  For updates to Claude Code, see the complete CHANGELOG.md.
</Tip>

### August 19, 2026

* The computer use tool is now generally available as `computer_toolset_20260801`.
* We've launched the browser use tool (`browser_toolset_20260801`).
* Both toolsets are available for Claude Fable 5 and friends.

### Not a date heading

Prose that must not be attributed to any date.

### August 7, 2026

* Managed Agents sessions can now have hard spend caps.

### July 2, 2026

* Ancient entry that watch_since must exclude.
EOF

reset_state() {
  rm -rf shared/platform-snapshots
  mkdir -p shared/platform-snapshots
  rm -f shared/platform-adoption-gaps.json
  printf '{ "watch_since": "2026-08-01" }\n' > shared/platform-support.json
}

run_watch() {
  # Runs the watcher with the given fixture; sets EXIT + writes output to $1.
  local out="$1" fixture="$2"
  EXIT=0
  PLATFORM_RELEASE_WATCH_FIXTURE="$fixture" node scripts/platform-release-watch.mjs > "$out" 2>&1 || EXIT=$?
}

# ============================================================================
# Test 1: happy path — two dates snapshotted, July excluded, gaps written
# ============================================================================
reset_state
run_watch "$WORK_DIR/run1.txt" "$FIXTURE"
if [ "$EXIT" = "0" ]; then
  log_pass "Happy path: exit 0"
else
  log_fail "Happy path exit" "expected 0, got $EXIT (output: $(cat "$WORK_DIR/run1.txt"))"
fi

if [ -f shared/platform-snapshots/2026-08-19.md ] && [ -f shared/platform-snapshots/2026-08-07.md ]; then
  log_pass "Snapshots written for both in-window dates"
else
  log_fail "Snapshots" "missing 2026-08-19.md or 2026-08-07.md"
fi

if [ ! -f shared/platform-snapshots/2026-07-02.md ]; then
  log_pass "watch_since excludes 2026-07-02"
else
  log_fail "watch_since" "2026-07-02.md was snapshotted despite watch_since 2026-08-01"
fi

if grep -qF 'browser_toolset_20260801' shared/platform-snapshots/2026-08-19.md; then
  log_pass "Snapshot body carries the bullet text"
else
  log_fail "Snapshot body" "expected bullet text in 2026-08-19.md"
fi

if grep -qE '^- ' shared/platform-snapshots/2026-08-19.md && ! grep -qE '^\* ' shared/platform-snapshots/2026-08-19.md; then
  log_pass "Bullets normalized from * to -"
else
  log_fail "Bullet normalization" "expected - bullets only in snapshot"
fi

if ! grep -qF 'must not be attributed' shared/platform-snapshots/2026-08-19.md; then
  log_pass "Non-date heading section not misattributed to a date"
else
  log_fail "Heading isolation" "prose under non-date heading leaked into 2026-08-19.md"
fi

GAPS_LEN=$(node -e 'console.log(JSON.parse(require("fs").readFileSync("shared/platform-adoption-gaps.json","utf8")).length)')
if [ "$GAPS_LEN" = "2" ]; then
  log_pass "Gaps file has exactly the 2 in-window dates"
else
  log_fail "Gaps length" "expected 2, got $GAPS_LEN"
fi

BULLETS=$(node -e 'const g=JSON.parse(require("fs").readFileSync("shared/platform-adoption-gaps.json","utf8")); console.log(g.find(e=>e.date==="2026-08-19").raw_bullets_count)')
if [ "$BULLETS" = "3" ]; then
  log_pass "raw_bullets_count correct for 2026-08-19 (3)"
else
  log_fail "raw_bullets_count" "expected 3, got $BULLETS"
fi

# ============================================================================
# Test 2: idempotence — second run finds nothing new, gaps preserved (pending)
# ============================================================================
run_watch "$WORK_DIR/run2.txt" "$FIXTURE"
if [ "$EXIT" = "0" ] && grep -qF 'nothing new' "$WORK_DIR/run2.txt"; then
  log_pass "Second run: nothing new (snapshot presence gates)"
else
  log_fail "Idempotence" "expected 'nothing new', got exit $EXIT: $(cat "$WORK_DIR/run2.txt")"
fi

GAPS_LEN=$(node -e 'console.log(JSON.parse(require("fs").readFileSync("shared/platform-adoption-gaps.json","utf8")).length)')
if [ "$GAPS_LEN" = "2" ]; then
  log_pass "Second run preserved the 2 pending (unfiled) entries"
else
  log_fail "Pending carry" "expected 2 preserved entries, got $GAPS_LEN"
fi

# ============================================================================
# Test 3: filed entries are pruned on the next nothing-new run
# ============================================================================
node -e '
const fs = require("fs");
const g = JSON.parse(fs.readFileSync("shared/platform-adoption-gaps.json","utf8"));
g.find(e => e.date === "2026-08-07").issues_filed_at = "2026-08-21T00:00:00Z";
fs.writeFileSync("shared/platform-adoption-gaps.json", JSON.stringify(g, null, 2) + "\n");
'
run_watch "$WORK_DIR/run3.txt" "$FIXTURE"
GAPS_LEN=$(node -e 'console.log(JSON.parse(require("fs").readFileSync("shared/platform-adoption-gaps.json","utf8")).length)')
DATES=$(node -e 'console.log(JSON.parse(require("fs").readFileSync("shared/platform-adoption-gaps.json","utf8")).map(e=>e.date).join(","))')
if [ "$EXIT" = "0" ] && [ "$GAPS_LEN" = "1" ] && [ "$DATES" = "2026-08-19" ]; then
  log_pass "Filed entry pruned; unfiled entry carried"
else
  log_fail "Filed pruning" "expected exit 0 + only 2026-08-19 remaining, got exit $EXIT, [$DATES]"
fi

# ============================================================================
# Test 4: zero dated headings → exit 1 (could-not-observe, never nothing-new)
# ============================================================================
GARBAGE="$WORK_DIR/garbage.md"
printf '<html><body>maintenance page</body></html>\n' > "$GARBAGE"
run_watch "$WORK_DIR/run4.txt" "$GARBAGE"
if [ "$EXIT" = "1" ] && grep -qF 'zero dated headings' "$WORK_DIR/run4.txt"; then
  log_pass "Garbage page: exit 1 with loud message"
else
  log_fail "Could-not-observe" "expected exit 1 + 'zero dated headings', got exit $EXIT"
fi

# ============================================================================
# Test 5: missing fixture path → exit 1
# ============================================================================
run_watch "$WORK_DIR/run5.txt" "$WORK_DIR/does-not-exist.md"
if [ "$EXIT" = "1" ]; then
  log_pass "Missing fixture: exit 1"
else
  log_fail "Missing fixture" "expected exit 1, got $EXIT"
fi

# ============================================================================
# Test 6: no watch_since config → all dates processed (null disables cutoff)
# ============================================================================
reset_state
rm -f shared/platform-support.json
run_watch "$WORK_DIR/run6.txt" "$FIXTURE"
if [ "$EXIT" = "0" ] && [ -f shared/platform-snapshots/2026-07-02.md ]; then
  log_pass "No watch_since: old date processed"
else
  log_fail "No watch_since" "expected exit 0 + 2026-07-02.md snapshotted, got exit $EXIT"
fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[ "$FAIL" = "0" ] || exit 1
exit 0
